+            | L::SystolicArrayConv2dIm2colNhwcHwioWithBlocking(args) => {
+                let weights = access(args[2]);
+                let data = access(args[3]);
+                let channels_first = matches!(enode, L::SystolicArrayConv2dNchwOihwWithBlocking(_) |
+                                                     L::SystolicArrayConv2dIm2colNchwOihwWithBlocking(_));
+                let h = if channels_first { 2 } else { 1 };
+                let out_h = (data[h] - num(args[4])) / num(args[6]) + 1;
+                let out_w = (data[h + 1] - num(args[5])) / num(args[7]) + 1;
+                let dims = if channels_first {
+                    [data[0], weights[0], out_h, out_w]
+                } else {
+                    [data[0], out_h, out_w, weights[3]]
+                };
+                access_fact(IxDyn(&dims), IxDyn(&[]))
+            }
+            L::ConstantTensor([value, target]) => match fact(*value) {
+                D::Literal(a) => return D::Literal(ndarray::ArrayD::from_elem(shape(*target).clone(), a[IxDyn(&[])])),
+                D::Num(n) => return D::Literal(ndarray::ArrayD::from_elem(shape(*target).clone(), *n as f64)),
+                _ => panic!("expected scalar constant"),
+            },
+            L::RelayOperatorCall(_) | L::AcceleratorCall(_) => {
+                panic!("opaque operator outside the access-pattern language")
+            }
+        };
+        result.access_pattern_shape_settled = settled.get();
+        result.contains_accelerator_calls = contains_calls.get();
+        D::AccessPattern(result)
     }
 }
